import{_ as r,C as i,o,c as s,a6 as l,E as n,j as a,a as d}from"./chunks/framework.CKIbuWFA.js";const _=JSON.parse('{"title":"LIVE フィードを読む・調べる","description":"","frontmatter":{"title":"LIVE フィードを読む・調べる","docId":"user.live.feed","translationKey":"user.live.feed","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4830f0a02244f46bfefb9b37c09d96c969688d022a0df90359c96c3e359af147","translationRevision":"957815be64ea5840b2e21b6ae73d5486891c2bfc0656701876345aaf02c88d48","order":20},"headers":[],"relativePath":"ja/user/live/feed.md","filePath":"ja/user/live/feed.md","lastUpdated":1794611623000}'),c={name:"ja/user/live/feed.md"};function p(u,e,f,h,m,b){const t=i("DemoFrame");return o(),s("div",null,[e[0]||(e[0]=l('<h1 id="read-and-inspect-the-live-feed" tabindex="-1">LIVE フィードを読む・調べる <a class="header-anchor" href="#read-and-inspect-the-live-feed" aria-label="Permalink to &quot;LIVE フィードを読む・調べる {#read-and-inspect-the-live-feed}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>イベントとフィールドを調べ、表示の一時停止とルームの切断を区別します。<a href="./connections.html">LIVE 接続</a> を用意するか、現在のフィード内のイベントを使います。フィードは件数に限りがある作業用表示で、配信全体の記録ではありません。</p><h2 id="inspect-activity" tabindex="-1">動きを確認する <a class="header-anchor" href="#inspect-activity" aria-label="Permalink to &quot;動きを確認する {#inspect-activity}&quot;">​</a></h2><ol><li><strong>ライブフィード</strong> を開き、接続状態で現在の配信者を確認します。</li><li>全イベント、チャット、ギフト、いいね、フォロー、入室、その他の交流からフィルターを選びます。検索と組み合わせ、投稿者、メッセージ、ギフト名、正確なギフト ID を探します。</li><li><strong>自動スクロールを一時停止</strong> で自動スクロールを止めて読みます。受信は継続し、未読数が増えることがあります。TikTok の切断や自動化の停止は行いません。</li><li>イベントを選びインスペクターを開きます。自動化用のフィールドを選ぶ前に種別と詳細を確認します。すべてのイベントにチャット、ギフト情報、視聴者 ID があるわけではありません。</li><li>視聴者名かアバターで追跡プロフィールを開きます。詳細パネルが隠れていればインスペクターの切り替えを使います。</li><li><strong>自動スクロールを再開</strong> または未読へのジャンプで新着へ戻ります。受信の有無を確認する際は検索を消し、全イベントを選びます。</li></ol><p>可能な場合はラベル付き操作にキーボードでフォーカスして使います。動きで読みにくい場合はスクロール停止が役立ちます。アバターがなくてもイニシャルが表示され、画像がなくても視聴者を識別できます。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>フィルターと詳細確認を利用できます。大量受信時は表示範囲が制限され、UI イベントの欠落が報告されることがあります。これは表示の指標なので、見えている行数を集計値にしないでください。<a href="./../points/statistics.html">分析</a> は永続化済み集計を別に照会します。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>空ならフィルターを外し、スクロールを再開して接続状態を確認します。静かなルームでも正常な場合があります。同じ配信者への再接続は対象を保持し、切り替えると対象が変わります。<strong>フィードを消去</strong> は作業用フィードだけを消し、ポイントや統計はリセットしません。欠落表示は<a href="./../preferences/troubleshooting.html">診断</a> で調べ、表示にない行がすべて配信元でも失われたとは判断しないでください。</p>',10)),n(t,{scenario:"feed",locale:"ja",title:"デモ: フィード"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[d("運用の詳細 "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "運用の詳細 {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,"この版の表示保持は最大 300 件、表示待ちの一時保存は最大 900 件です。最も古いギフト以外の行から除き、他の種類がなくなってからギフトを除きます。そのため古いギフトが新しいチャットより長く残る場合があります。スクロール停止中も受信は続き、保持は保証されません。フィルターでは消えた行を戻せません。欠落表示を理由にポイントやアクションを再実行しないでください。",-1))])}const g=r(c,[["render",p]]);export{_ as __pageData,g as default};
